import{_ as n,a0 as p,w as s,s as d,I as o,x as t,a1 as r,A as i,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"在CentOS上配置基於主機的入侵檢測系統（IDS） | LCTT x X-CMD","titleTemplate":false,"description":"在CentOS上配置基於主機的入侵檢測系統（IDS） | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在CentOS上配置基於主機的入侵檢測系統（IDS） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在CentOS上配置基於主機的入侵檢測系統（IDS） | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141008 How to configure a host intrusion detection system on CentOS","title":"在CentOS上配置基於主機的入侵檢測系統（IDS）","tag":"201411","desc":""},"relativePath":"201411/20141008 How to configure a host intrusion detection system on CentOS.md","filePath":"[post].md"}'),c={name:"201411/20141008 How to configure a host intrusion detection system on CentOS.md"};function m(h,e,f,u,A,I){const a=p("Link");return s(),d("div",null,[e[15]||(e[15]=o("h1",{id:"在centos上配置基於主機的入侵檢測系統-ids",tabindex:"-1"},[t("在CentOS上配置基於主機的入侵檢測系統（IDS） "),o("a",{class:"header-anchor",href:"#在centos上配置基於主機的入侵檢測系統-ids","aria-label":"Permalink to “在CentOS上配置基於主機的入侵檢測系統（IDS）”"},"​")],-1)),e[16]||(e[16]=o("p",null,"所有系統管理員想要在他們生產服務器上首先要部署的安全手段之一，就是檢測文件篡改的機制——不僅僅是文件內容，而且也包括它們的屬性。",-1)),o("p",null,[r(a,{href:"http://aide.sourceforge.net/"},{default:i(()=>[...e[0]||(e[0]=[t("AIDE",-1)])]),_:1}),e[1]||(e[1]=t(" （“高級入侵檢測環境”的簡稱）是一個開源的基於主機的入侵檢測系統。AIDE通過檢查大量文件屬性的不一致性來檢查系統二進制文件和基本配置文件的完整性，這些文件屬性包括權限、文件類型、索引節點、鏈接數、鏈接名、用户、組、文件大小、塊計數、修改時間、添加時間、創建時間、acl、SELinux安全上下文、xattrs，以及md5/sha校驗值在內的各種特徵。",-1))]),e[17]||(e[17]=l(`<p>AIDE通過掃描一台（未被篡改）的Linux服務器的文件系統來構建文件屬性資料庫，以後將服務器文件屬性與資料庫中的進行校對，然後在服務器運行時對被修改的索引了的文件發出警告。出於這個原因，AIDE必須在系統更新後或其配置文件進行合法修改後重新對受保護的文件做索引。</p><p>對於某些客户，他們可能會根據他們的安全策略在他們的服務器上強制安裝某種入侵檢測系統。但是，不管客户是否要求，系統管理員都應該部署一個入侵檢測系統，這通常是一個很好的做法。</p><h3 id="在-centos或rhel-上安裝aide" tabindex="-1">在 CentOS或RHEL 上安裝AIDE <a class="header-anchor" href="#在-centos或rhel-上安裝aide" aria-label="Permalink to “在 CentOS或RHEL 上安裝AIDE”">​</a></h3><p>AIDE的初始安裝（同時是首次運行）最好是在系統剛安裝完後，並且沒有任何服務暴露在互聯網甚至局域網時。在這個早期階段，我們可以將來自外部的一切闖入和破壞風險降到最低限度。事實上，這也是確保系統在AIDE構建其初始資料庫時保持乾淨的唯一途徑。（LCTT 譯註：當然，如果你的安裝源本身就存在安全隱患，則無法建立可信的數據記錄）</p><p>出於上面的原因，在安裝完系統後，我們可以執行下面的命令安裝AIDE：</p><pre><code> # yum install aide 
</code></pre><p>我們需要將我們的機器從網絡斷開，並實施下面所述的一些基本配置任務。</p><h3 id="配置aide" tabindex="-1">配置AIDE <a class="header-anchor" href="#配置aide" aria-label="Permalink to “配置AIDE”">​</a></h3><p>默認配置文件是/etc/aide.conf，該文件介紹了幾個示例保護規則（如FIPSR，NORMAL，DIR，DATAONLY），各個規則後面跟着一個等號以及要檢查的文件屬性列表，或者某些預定義的規則（由+分隔）。你也可以使用此種格式自定義規則。</p><p><img src="https://farm3.staticflickr.com/2947/15446746115_7d0a291b0a_o.png" alt=""></p><pre><code>FIPSR = p+i+n+u+g+s+m+c+acl+selinux+xattrs+sha256
NORMAL = FIPSR+sha512
</code></pre><p>例如，上面的例子説明，NORMAL規則將檢查下列屬性的不一致性：權限（p）、索引節點（i）、鏈接數（n）、用户（u）、組（g）、大小（s）、修改時間（m）、創建時間（c）、ACL（acl）、SELinux（selinux）、xattrs（xattr）、SHA256/SHA512校驗和（sha256和sha512）。</p><p>定義的規則可靈活地用於不同的目錄和文件（用正則表達式表示）。</p><p><img src="https://farm6.staticflickr.com/5601/15259978179_f93b757c56_o.png" alt=""></p><p>條目之前的感嘆號（！）告訴AIDE忽略子目錄（或目錄中的文件），對於這些可以另外定義規則。</p><p>在上面的例子中，PERMS是用於/etc機器子目錄和文件的默認規則。然而，對於/etc中的備份文件（如/etc/.*~）則不應用任何規則，也沒有規則用於/etc/mtab文件。對於/etc中的其它一些選定的子目錄或文件，使用NORMAL規則替代默認規則PERMS。</p><p>定義並應用正確的規則到系統中正確的位置，是使用AIDE最難的一部分，但作一個好的判斷是一個良好的開始。作為首要的一條規則，不要檢查不必要的屬性。例如，檢查/var/log或/var/spool裏頭的文件的修改時間將導致大量誤報，因為許多的應用程序和守護進程經常會寫入內容到該位置，而這些內容都沒有問題。此外，檢查多個校驗值可能會加強安全性，但隨之而來的是AIDE的運行時間的增加。</p><p>可選的，如果你使用MAILTO變量指定電子郵件地址，就可以將檢查結果發送到你的郵箱。將下面這一行放到/etc/aide.conf中的任何位置即可。</p><pre><code>MAILTO=root@localhost
</code></pre><h3 id="首次運行aide" tabindex="-1">首次運行AIDE <a class="header-anchor" href="#首次運行aide" aria-label="Permalink to “首次運行AIDE”">​</a></h3><p>運行以下命令來初始化AIDE資料庫：</p><pre><code> # aide --init 
</code></pre><p><img src="https://farm3.staticflickr.com/2942/15446399402_198472e983_o.png" alt=""></p><p>根據/etc/aide.conf生成的/var/lib/aide/aide.db.new.gz文件需要被重命名為/var/lib/aide/aide.db.gz，以便AIDE能讀取它：</p><pre><code> # mv /var/lib/aide/aide.db.new.gz /var/lib/aide.db.gz 
</code></pre><p>現在，是時候來將我們的系統與資料庫進行第一次校對了。任務很簡單，只需運行：</p><pre><code> # aide 
</code></pre><p>在沒有選項時，AIDE假定使用了--check選項。</p><p>如果在資料庫創建後沒有對系統做過任何修改，AIDE將會以OK信息來結束本次校對。</p><p><img src="https://farm3.staticflickr.com/2948/15260041950_f568b3996a_o.png" alt=""></p><h3 id="生產環境中管理aide" tabindex="-1">生產環境中管理AIDE <a class="header-anchor" href="#生產環境中管理aide" aria-label="Permalink to “生產環境中管理AIDE”">​</a></h3><p>在構建了一個初始AIDE資料庫後，作為不斷進行的系統管理活動，你常常需要因為某些合法的理由更新受保護的服務器。每次服務器更新後，你必須重新構建AIDE資料庫，以更新資料庫內容。要完成該任務，請執行以下命令：</p><pre><code> # aide --update 
</code></pre><p>要使用AIDE保護生產系統，可能最好通過任務計劃調用AIDE來週期性檢查不一致性。例如，要讓AIDE每天運行一次，並將結果發送到郵箱：</p><pre><code> # crontab -e 
</code></pre><hr><pre><code>0 0 * * * /usr/sbin/aide --check | /usr/bin/mail -s &quot;AIDE run for $HOSTNAME&quot; your@email.com
</code></pre><h3 id="測試aide檢查文件篡改" tabindex="-1">測試AIDE檢查文件篡改 <a class="header-anchor" href="#測試aide檢查文件篡改" aria-label="Permalink to “測試AIDE檢查文件篡改”">​</a></h3><p>下面的測試環境將演示AIDE是如何來檢查文件的完整性的。</p><h4 id="測試環境-1" tabindex="-1">測試環境 1 <a class="header-anchor" href="#測試環境-1" aria-label="Permalink to “測試環境 1”">​</a></h4><p>讓我們添加一個新文件（如/etc/fake）。</p><pre><code># cat /dev/null &gt; /etc/fake 
</code></pre><p><img src="https://farm3.staticflickr.com/2941/15260140358_f1d758d354_o.png" alt=""></p><h4 id="測試環境-2" tabindex="-1">測試環境 2 <a class="header-anchor" href="#測試環境-2" aria-label="Permalink to “測試環境 2”">​</a></h4><p>讓我們修改文件權限，然後看看它是否被檢測到。</p><pre><code> # chmod 644 /etc/aide.conf 
</code></pre><h4 id="測試環境-3" tabindex="-1">測試環境 3 <a class="header-anchor" href="#測試環境-3" aria-label="Permalink to “測試環境 3”">​</a></h4><p>最後，讓我們修改文件內容（如，添加一個註釋行到/etc/aide.conf）。</p><pre><code>echo &quot;#This is a comment&quot; &gt;&gt; /etc/aide.conf 
</code></pre><p><img src="https://farm4.staticflickr.com/3936/15259978229_3ff1ea950e_b.jpg" alt=""></p><p>上面的截圖中，第一欄顯示了文件的屬性，第二欄是AIDE資料庫中的值，而第三欄是更新後的值。第三欄中空白部分表示該屬性沒有改動（如本例中的ACL）。</p><h3 id="結尾" tabindex="-1">結尾 <a class="header-anchor" href="#結尾" aria-label="Permalink to “結尾”">​</a></h3><p>如果你曾經發現你自己有很好的理由確信系統被入侵了，但是第一眼又不能確定到底哪些東西被改動了，那麼像AIDE這樣一個基於主機的入侵檢測系統就會很有幫助了，因為它可以幫助你很快識別出哪些東西被改動過，而不是通過猜測來浪費寶貴的時間。</p><hr>`,54)),o("p",null,[e[3]||(e[3]=t("via: ",-1)),r(a,{href:"http://xmodulo.com/host-intrusion-detection-system-centos.html"},{default:i(()=>[...e[2]||(e[2]=[t("http://xmodulo.com/host-intrusion-detection-system-centos.html",-1)])]),_:1})]),o("p",null,[e[7]||(e[7]=t("作者：",-1)),r(a,{href:"http://xmodulo.com/author/gabriel"},{default:i(()=>[...e[4]||(e[4]=[t("Gabriel Cánepa",-1)])]),_:1}),e[8]||(e[8]=t(" 譯者：",-1)),r(a,{href:"https://github.com/GOLinux"},{default:i(()=>[...e[5]||(e[5]=[t("GOLinux",-1)])]),_:1}),e[9]||(e[9]=t(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[6]||(e[6]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[12]||(e[12]=t("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[10]||(e[10]=[t("LCTT",-1)])]),_:1}),e[13]||(e[13]=t(" 原創翻譯，",-1)),r(a,{href:"http://linux.cn/"},{default:i(()=>[...e[11]||(e[11]=[t("Linux中國",-1)])]),_:1}),e[14]||(e[14]=t(" 榮譽推出",-1))])])}const x=n(c,[["render",m]]);export{b as __pageData,x as default};
